def choose_move(observation):
    def clamp_step(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pos_pair(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def step_toward(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def step_away(a, b):
        return [clamp_step(a[0] - b[0]), clamp_step(a[1] - b[1])]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos_pair(observation.get("self_position", (0, 0)))
    ox, oy = pos_pair(observation.get("opponent_position", (sx, sy)))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)
    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        corners = [(0, 0), (0, max(0, h - 1)), (max(0, w - 1), 0), (max(0, w - 1), max(0, h - 1))]
        target = corners[0]
        best_score = -10**9
        for c in corners:
            score = manhattan(c, opp_pos) * 2 + manhattan(c, self_pos)
            if score > best_score:
                best_score = score
                target = c
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("neutral_cells") or []
        if targets:
            best = None
            best_score = 10**9
            for item in targets:
                p = pos_pair(item, self_pos)
                score = manhattan(self_pos, p) - manhattan(opp_pos, p) * 0.25
                if score < best_score:
                    best_score = score
                    best = p
            if best is not None:
                return step_toward(self_pos, best)
        return step_away(self_pos, opp_pos)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        best = None
        best_score = 10**9
        for item in resources:
            p = pos_pair(item, self_pos)
            score = manhattan(self_pos, p) - manhattan(opp_pos, p) * 0.5
            if score < best_score:
                best_score = score
                best = p
        if best is not None:
            return step_toward(self_pos, best)

    if manhattan(self_pos, opp_pos) <= 2:
        return step_away(self_pos, opp_pos)

    if w and h:
        center = (w // 2, h // 2)
        return step_toward(self_pos, center)

    return [0, 0]

